CREATE OR REPLACE FUNCTION public.establish_account_deletion_barrier(p_user_id uuid, p_policy_version integer, p_acknowledged boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE j public.account_deletion_jobs; prior public.account_deletion_jobs;
BEGIN
 PERFORM 1 FROM public.account_deletion_contract_gate WHERE singleton FOR SHARE;
 IF p_user_id IS NULL OR p_acknowledged IS DISTINCT FROM true THEN RAISE EXCEPTION 'verified disclosure acknowledgement required'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.account_deletion_contract_gate WHERE requests_enabled)
 OR NOT EXISTS(SELECT 1 FROM public.account_deletion_policy_version WHERE version=p_policy_version AND technical_status='approved') THEN RAISE EXCEPTION 'deletion contract approval required'; END IF;
 -- Serialization is shared with every monitored writer. There is no window
 -- between the durable request and the operational restriction.
 INSERT INTO public.account_deletion_write_guard(user_id) VALUES(p_user_id) ON CONFLICT DO NOTHING;
 PERFORM 1 FROM public.account_deletion_write_guard WHERE user_id=p_user_id FOR UPDATE;
 SELECT * INTO prior FROM public.account_deletion_jobs WHERE user_id=p_user_id;
 IF prior.id IS NOT NULL THEN j:=prior;
 ELSE
  IF NOT EXISTS(SELECT 1 FROM auth.users WHERE id=p_user_id) THEN RAISE EXCEPTION 'verified identity required'; END IF;
  INSERT INTO public.account_deletion_jobs(user_id,policy_version,stage) VALUES(p_user_id,p_policy_version,'restricted') RETURNING * INTO j;
  INSERT INTO public.account_deletion_audit(job_id,actor_user_id,event_code) VALUES(j.id,p_user_id,'request_acknowledged_barrier_established');
 END IF;
 UPDATE public.account_deletion_write_guard SET restricted=true,job_id=j.id,changed_at=now() WHERE user_id=p_user_id;
 RETURN jsonb_build_object('contractVersion',1,'policyVersion',j.policy_version,'requestId',j.id,'status','restricted');
END;
$function$

CREATE OR REPLACE FUNCTION public.read_account_deletion_delivered_receipt(p_request uuid, p_credential text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE j public.account_deletion_jobs;result jsonb;
BEGIN
 IF p_credential IS NULL OR p_credential !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='deletion_receipt_unavailable';END IF;
 SELECT job.* INTO j FROM public.account_deletion_receipt_access a JOIN public.account_deletion_jobs job ON job.id=a.job_id
 WHERE a.job_id=p_request AND a.expires_at>clock_timestamp() AND a.token_digest=sha256(convert_to(p_credential,'UTF8'));
 IF j.id IS NULL OR NOT public.account_deletion_rule_allowed(j.policy_version,'receipt.delivery') OR
 (j.status='completed' AND NOT EXISTS(SELECT 1 FROM public.account_deletion_completion_receipt WHERE job_id=j.id AND expires_at>clock_timestamp())) THEN
  RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='deletion_receipt_unavailable';END IF;
 result:=public.read_account_deletion_lifecycle(j.id,j.user_id);
 -- Never return retained case categories, actor/user IDs, evidence or credentials.
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.read_account_deletion_lifecycle(p_request uuid, p_user uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE j public.account_deletion_jobs;state text;exceptions integer;
BEGIN
 SELECT * INTO j FROM public.account_deletion_jobs WHERE id=p_request AND user_id=p_user;
 IF j.id IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='deletion_receipt_unavailable';END IF;
 state:=CASE WHEN j.review_required THEN 'manual_review' WHEN j.status='pending' THEN 'restricted' WHEN j.status='retry' THEN 'failed' ELSE j.status END;
 IF state='completed' THEN
  SELECT exception_count INTO exceptions FROM public.account_deletion_completion_receipt WHERE job_id=j.id AND policy_version=j.policy_version AND expires_at>clock_timestamp();
  IF exceptions IS NULL THEN state:='manual_review';END IF;
 END IF;
 INSERT INTO public.account_deletion_audit(job_id,event_code) VALUES(j.id,'minimal_lifecycle_receipt_read');
 RETURN jsonb_build_object('contractVersion',1,'requestId',j.id,'policyVersion',j.policy_version,'status',state,'retainedExceptions',exceptions);
END $function$

CREATE OR REPLACE FUNCTION public.request_verified_account_deletion_core(p_user uuid, p_policy integer, p_acknowledged boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE contract jsonb;
BEGIN
 IF p_policy<>1 THEN RAISE EXCEPTION 'unsupported disclosure contract';END IF;
 contract:=public.account_deletion_contract_status();
 IF contract->>'requestsEnabled'<>'true' THEN RAISE EXCEPTION 'deletion contract approval required';END IF;
 RETURN public.establish_account_deletion_barrier(p_user,(contract->>'policyVersion')::integer,p_acknowledged);
END $function$

CREATE OR REPLACE FUNCTION public.request_verified_account_deletion(p_user uuid, p_policy integer, p_acknowledged boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE result jsonb;j public.account_deletion_jobs;r public.account_deletion_retention_rule;secret text;deadline timestamptz;
BEGIN
 result:=public.request_verified_account_deletion_core(p_user,p_policy,p_acknowledged);
 SELECT * INTO j FROM public.account_deletion_jobs WHERE id=(result->>'requestId')::uuid AND user_id=p_user FOR UPDATE;
 IF NOT public.account_deletion_rule_allowed(j.policy_version,'receipt.delivery') THEN RETURN result;END IF;
 SELECT * INTO r FROM public.account_deletion_retention_rule WHERE policy_version=j.policy_version AND category='receipt_access';
 IF r.approval_status IS DISTINCT FROM 'approved' OR r.period IS NULL OR r.lawful_basis IS NULL OR r.start_event IS DISTINCT FROM 'barrier_established' OR r.minimum_fields IS DISTINCT FROM ARRAY['token_digest','expires_at'] THEN RETURN result;END IF;
 deadline:=j.requested_at+r.period;
 IF deadline<=clock_timestamp() THEN RETURN result;END IF;
 secret:=replace(gen_random_uuid()::text||gen_random_uuid()::text,'-','');
 INSERT INTO public.account_deletion_receipt_access VALUES(j.id,sha256(convert_to(secret,'UTF8')),deadline)
 ON CONFLICT(job_id) DO UPDATE SET token_digest=excluded.token_digest,expires_at=excluded.expires_at;
 INSERT INTO public.account_deletion_audit(job_id,event_code) VALUES(j.id,'receipt_only_access_issued');
 RETURN result||jsonb_build_object('receiptAccess',jsonb_build_object('credential',secret,'expiresAt',deadline));
END $function$

CREATE OR REPLACE FUNCTION public.set_account_deletion_intake(p_state text, p_expected bigint, p_reason text, p_operation uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
#variable_conflict use_variable
DECLARE actor uuid; gate public.account_deletion_contract_gate; prior public.ops_command_receipt;
 payload jsonb; result jsonb; old_state jsonb;
BEGIN
 actor:=public.ops_assert_capability('settings.security');
 IF NOT EXISTS(SELECT 1 FROM public.admin_users WHERE user_id=actor AND role::text IN ('super_admin','security_admin')) THEN
  RAISE EXCEPTION 'Security administrator required' USING ERRCODE='42501'; END IF;
 IF p_state IS NULL OR p_state NOT IN ('enabled','disabled','hold') OR p_expected IS NULL OR p_expected<0 OR p_operation IS NULL
 OR length(trim(coalesce(p_reason,''))) NOT BETWEEN 10 AND 1000 THEN
  RAISE EXCEPTION 'State, version, operation and reason required' USING ERRCODE='22023'; END IF;
 payload:=jsonb_build_object('state',p_state,'expected',p_expected,'reason',trim(p_reason));
 -- Serialize all commands on the authority row; same-operation retries return the committed receipt.
 SELECT * INTO gate FROM public.account_deletion_contract_gate WHERE singleton FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Intake control unavailable' USING ERRCODE='55000'; END IF;
 SELECT * INTO prior FROM public.ops_command_receipt WHERE actor_user_id=actor AND operation=p_operation;
 IF FOUND THEN
  IF prior.kind<>'deletion.intake' OR prior.payload<>payload THEN RAISE EXCEPTION 'Operation reused' USING ERRCODE='22023'; END IF;
  RETURN prior.result;
 END IF;
 IF gate.operating_version<>p_expected THEN RAISE EXCEPTION 'Operating state changed' USING ERRCODE='40001'; END IF;
 IF p_state='enabled' AND NOT (
  gate.catalog_digest IS NOT NULL AND gate.catalog_verified_at IS NOT NULL AND gate.catalog_review_reference IS NOT NULL
  AND gate.barrier_verified_at IS NOT NULL AND gate.disposition_verified_at IS NOT NULL
  AND EXISTS(SELECT 1 FROM public.account_deletion_policy_version WHERE version=gate.active_policy_version AND technical_status='approved')
  AND public.account_deletion_rule_allowed(gate.active_policy_version,'personal.erase')
  AND public.account_deletion_rule_allowed(gate.active_policy_version,'external.erase')
  AND public.account_deletion_rule_allowed(gate.active_policy_version,'receipt.complete')
  AND public.account_deletion_rule_allowed(gate.active_policy_version,'restore.suppress')) THEN
  RAISE EXCEPTION 'Existing deletion policy approvals and readiness evidence required' USING ERRCODE='55000'; END IF;
 old_state:=jsonb_build_object('state',gate.operating_state,'version',gate.operating_version);
 UPDATE public.account_deletion_contract_gate SET operating_state=p_state,operating_version=operating_version+1,
  operating_changed_at=clock_timestamp(),operating_changed_by=actor,operating_reason=trim(p_reason) WHERE singleton;
 result:=public.account_deletion_intake_status();
 PERFORM public.ops_audit('settings.security','account_deletion_intake','global',old_state,result,trim(p_reason),p_operation);
 INSERT INTO public.ops_command_receipt(actor_user_id,operation,kind,payload,result) VALUES(actor,p_operation,'deletion.intake',payload,result);
 RETURN result;
END $function$
